def time_to_seconds(t):
    return t.hour * 3600 + t.minute * 60 + t.second + t.microsecond / 1000000.0


def datetime_normalize(truncate_datetime, obj):
    import datetime
    if isinstance(obj, datetime.datetime):
        if truncate_datetime == 'second':
            return obj.replace(microsecond=0)
        elif truncate_datetime == 'minute':
            return obj.replace(second=0, microsecond=0)
        elif truncate_datetime == 'hour':
            return obj.replace(minute=0, second=0, microsecond=0)
        elif truncate_datetime == 'day':
            return obj.replace(hour=0, minute=0, second=0, microsecond=0)
        elif truncate_datetime == 'month':
            return obj.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
        elif truncate_datetime == 'year':
            return obj.replace(month=1, day=1, hour=0, minute=0, second=0, microsecond=0)
    elif isinstance(obj, datetime.time):
        if truncate_datetime == 'second':
            return obj.replace(microsecond=0)
        elif truncate_datetime == 'minute':
            return obj.replace(second=0, microsecond=0)
        elif truncate_datetime == 'hour':
            return obj.replace(minute=0, second=0, microsecond=0)
    return obj


def get_truncate_datetime(truncate_datetime):
    valid_options = {'second', 'minute', 'hour', 'day', 'month', 'year'}
    if truncate_datetime not in valid_options:
        raise ValueError(f"Invalid truncate_datetime option: {truncate_datetime}. Valid options are: {valid_options}")
    return truncate_datetime
